pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // the initial owner in the reference contract is address(this) because setUp() deploys C.
        // we need another address as caller; exclude the initial owner to test the onlyOwner guard.
        vm.assume(caller != address(this));
        // ensure caller and newOwner are distinct to observe a potential ownership change.
        vm.assume(caller != newOwner);
        // ensure newOwner is not the current owner (which is address(this)) so that a successful
        // transfer would actually change the owner.
        vm.assume(newOwner != address(this));

        address ownerBefore = c.owner();
        vm.prank(caller);
        c.transferOwnership(newOwner);
        address ownerAfter = c.owner();

        // Rule: if the caller is not the current owner before the call, the owner must remain unchanged.
        // This holds for the reference contract (msg.sender check) and fails for the buggy one
        // (require(true) always passes) when the fuzzer picks a caller != original owner.
        assertTrue(ownerAfter == ownerBefore);
    }
}

