pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address originalOwner, address newOwner) public {
        vm.assume(originalOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(originalOwner != newOwner);

        // Set up the original owner
        vm.prank(originalOwner);
        c.transferOwnership(originalOwner);

        address ownerBefore = c.owner();
        assertEq(ownerBefore, originalOwner);

        // The original owner calls transferOwnership to change to newOwner
        vm.prank(originalOwner);
        c.transferOwnership(newOwner);

        address ownerAfter = c.owner();
        assertEq(ownerAfter, newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        // 1. Restrict the domain: caller must be current owner and _newOwner must differ to detect bug
        vm.assume(_newOwner != c.owner());

        // 2. Prank as current owner to call transferOwnership
        vm.prank(c.owner());
        c.transferOwnership(_newOwner);

        // 3. Assert that after a successful call, owner is updated to _newOwner
        assertTrue(c.owner() == _newOwner, "owner should be updated to _newOwner");
    }
}
